        "priorita": "Alta",
        "id_gruppo": 1,
        "link": "https://www.scmp.com/news/china/diplomacy/article/3348706/how-donald-trump-could-reframe-us-goals-iran-war-justify-finishing-it?utm_source=rss_feed",
